def bfs_distances(starts):
    dist = {}
    dq = deque()
    for r, c, v in starts:
        dist[(r, c)] = 0
        dq.append((r, c))

    while dq:
        r, c = dq.popleft()
        for dr, dc in [(1, 1), (1, -1), (-1, 1), (-1, -1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 25 and 0 <= nc < 25:
                if (nr, nc) not in dist:
                    dist[(nr, nc)] = dist[(r, c)] + 1
                    dq.append((nr, nc))
    return dist

