from collections import Counter

def special_on_cell_diag(r, c):
    """Return what special values are on each diagonal direction"""
    results = []
    for name, (dr, dc) in [("SE", (1, 1)), ("SW", (1, -1)), ("NE", (-1, 1)), ("NW", (-1, -1))]:
        cr, cc = r + dr, c + dc
        while 0 <= cr < 25 and 0 <= cc < 25:
