# Build final submission based on my best model
special_cells = [
    (0, 6, 6),   (2, 16, 6),  (3, 14, 4), (4, 9, 6),
    (5, 5, 6),   (5, 12, 5),  (6, 8, 7),  (7, 14, 5),
