]

output_grid = []
for r in range(13):
    row = []
    for c in range(19):
        candidates = []
        # Find special cells on anti-diagonal
        for sr, sc, sv in special_cells:
            if r + c == sr + sc:
                candidates.append((sv, abs(r - sr), 'anti'))
        # Find special cells on main diagonal
        for sr, sc, sv in special_cells:
            if r - c == sr - sc:
                candidates.append((sv, abs(r - sr), 'main'))

        if candidates:
            row.append(min(candidates, key=lambda x: x[1])[0])
        else:
            row.append(1)
    output_grid.append(row)

